#if UNITY_EDITOR
using System.Linq; using UnityEditor;
namespace UnityCli { public class BuildSceneAddTool : IUnityCliTool<BuildSceneAddTool.Request, BuildSceneMutationResult> { public sealed class Request { [UnityCliRequired] public string Path { get; set; } } public ToolDescriptor Describe() => new() { Name = "build.scene.add", Summary = "Add an enabled scene to persistent Unity Build Settings.", Description = "Adds path to EditorBuildSettings as an enabled scene when absent. Requires --yes because it writes ProjectSettings. dryRun=true previews without writing. Available in Edit and Play mode.", Group = "build", Version = "1.0.0", DestructiveHint = true, SupportsDryRun = true, SideEffects = new[] { "project-settings-write" }, Target = "editor", PlayModeSupport = "editor-only", DefaultTimeoutMs = 30000, MaxTimeoutMs = 600000, Examples = new[] { new ToolExample { Description = "Add main scene", Input = new Request { Path = "Assets/Scenes/Main.unity" }, Execution = new ToolExampleExecution { DryRun = true } } } }; public System.Threading.Tasks.ValueTask<BuildSceneMutationResult> ExecuteAsync(Request request, UnityCliProjectToolContext ctx, System.Threading.CancellationToken ct = default) { var path = BuildToolSupport.NormalizeAssetPath(request.Path); if (string.IsNullOrEmpty(path)) throw new UnityCliBridge.BridgeCommandException("E_BUILD_SCENE_PATH_REQUIRED", "build.scene.add requires path.", "Pass a scene path such as Assets/Scenes/Main.unity."); var list = (EditorBuildSettings.scenes ?? new EditorBuildSettingsScene[0]).ToList(); if (!ctx.DryRun && !list.Any(scene => scene.path == path)) { list.Add(new EditorBuildSettingsScene(path, true)); EditorBuildSettings.scenes = list.ToArray(); } return new(new BuildSceneMutationResult { Path = path, Count = list.Count + (ctx.DryRun && !list.Any(scene => scene.path == path) ? 1 : 0), DryRun = ctx.DryRun }); } } }
#endif
